-- 検証: 8 行とも sections が更新され、本文に /tmp-preview が残っていないこと
select left(title, 24) as title, jsonb_array_length(sections) as n, length(sections::text) as len, (sections::text like '%/tmp-preview/%') as has_local, hero_brand from works where id in ('894c880d-8a59-48e0-aebc-eb25c904cb2b','94734d87-a54f-4588-a521-e9ea414b9ef0','d0fc8a40-013a-4c58-9fed-334dd116b0ad','8e73db10-2845-46bd-b602-bd646cf7e382','58d46b66-a6de-4b70-b1b7-db282b6e0a7a','204128f2-c84b-46c9-9427-248a8c290b86','177adc06-5b0d-4185-bf42-431651f5c96f','0d524339-325d-4683-87bf-d2636adf8e58') order by sort_order;
